function earliestCrossing(grid: number[][]): number {
  const n = grid.length;
  const reach = (t: number): boolean => {
    if (grid[0][0] > t) return false;
    const seen = new Uint8Array(n * n);
    const queue = [0];
    seen[0] = 1;
    for (let i = 0; i < queue.length; i++) {
      const r = Math.floor(queue[i] / n), c = queue[i] % n;
      if (r === n - 1 && c === n - 1) return true;
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr < 0 || nc < 0 || nr >= n || nc >= n || seen[nr * n + nc] || grid[nr][nc] > t) continue;
        seen[nr * n + nc] = 1;
        queue.push(nr * n + nc);
      }
    }
    return false;
  };
  let lo = Math.max(grid[0][0], grid[n - 1][n - 1]), hi = n * n - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (reach(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

